    display: none;
    width: 100%;
    flex-direction: column;
    align-items: stretch;
    padding-top: 10px;
    border-top: 1.5px solid #e2e8f0;
  }
  .cl-nav-menu.is-open {
    display: flex;
  }
  .cl-nav-Container {
    flex-wrap: wrap;
  }
  .cl-nav-actions {
    margin-left: 0;
    padding-top: 6px;
  }
