const snippets = {
  html: '<section class="card-grid">\n  <article class="feature-card">\n    <h3>Chuẩn HTML5 Ngữ nghĩa</h3>\n    <p>Sạch sẽ, dễ bảo trì.</p>\n  </article>\n</section>',
